private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Create a new linked list from the left subtree of node
    TreeNode<T> parent = node.getLeft();
    TreeNode<T> left = node.getLeft().getRight();

    // Relink the nodes to form a new parent-child relationship
    node.setLeft(left);
    parent.setRight(node);

    return parent;
}

