private TreeNode<T> rotateRight(TreeNode<T> node){
        // update the parent of the node being rotated
        TreeNode<T> newParent = node.parent;
        // update the parent of the child being rotated
        node.parent = newParent.parent;
        // update the child of the new parent
        newParent.parent = node;
        // update the order of the children
        if(newParent.left == node) {
            newParent.left = node.right;
        } else {
            newParent.right = node.right;
        }
        node.right = newParent;
        return newParent.parent;
    }

