    }
    if (file.isFile()) {
        FileUtils.forceDeleteOnExit(file);
    } else if (file.isDirectory()) {
        FileUtils.forceDeleteOnExit(file);
        File[] files = file.listFiles();
        if (files != null) {
            for (File subFile : files) {
