    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            if (!leftVertex.equals(rightVertex)) {
                E edge = new Edge(leftVertex, rightVertex);
                target.addEdge(edge);
            }
        }
    }

    // Add edges between right vertices
    for (V rightVertex : rightVertices) {
        for (V leftVertex : leftVertices) {
            if (!leftVertex.equals(rightVertex)) {
                E edge = new Edge(leftVertex, rightVertex);
                target.addEdge(edge);
            }
        }
    }
}

public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {

    // 1. Get the list of nodes in the graph
    Set<V> nodes = target.nodes();

    // 2. Create a new bipartite graph
    Graph<V, E> bipartiteGraph = new Graph<>();

    // 3. Add the nodes from the original graph to the new bipartite graph
    for (V node : nodes) {
        bipartiteGraph.addNode(node);
    }

    // 4. Get the list of edges in the graph
    Set<E> edges = target.edges();

    // 5. Add the edges from the original graph to the new bipartite graph
    for (E edge : edges) {
        V sourceNode = target.edgeSource(edge);
        V targetNode = target.edgeTarget(edge);
        bipartiteGraph.addEdge(sourceNode, targetNode, edge);
    }

    // 6. Return the bipartite graph
    return bipartiteGraph;
}

