private static Class<?> resolveArgument(Type actualTypeArgument, Class<?> targetType) {
    if (actualTypeArgument instanceof Class) {
        return (Class<?>) actualTypeArgument;
    } else if (actualTypeArgument instanceof TypeVariable) {
        return resolveTypeVariable(targetType, (TypeVariable<?>) actualTypeArgument);
    } else if (actualTypeArgument instanceof WildcardType) {
        return resolveWildcardType(targetType, (WildcardType) actualTypeArgument);
    } else {
        return null;
    }
}

private static Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    TypeVariable<?> targetTypeVariable = targetType.getTypeParameters()[typeVariable.getIndex()];
    return targetType.getTypeParameters()[targetTypeVariable.getIndex()];
}

private static Class<?> resolveWildcardType(Class<?> targetType, WildcardType wildcardType) {
    Type[] upperBounds = wildcardType.getUpperBounds();
    if (upperBounds.length == 1) {
        return (Class<?>) wildcardType.getUpperBounds()[0];
    }

    Type[] lowerBounds = wildcardType.getLowerBounds();
    if (lowerBounds.length > 0) {
        return (Class<?>) lowerBounds[0];
    }

    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    if (typeArguments.length == 0) {
        return null;
    }

    Class<?>[] argumentClasses = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            argumentClasses[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof TypeVariable) {
            argumentClasses[i] = findBoundClass((TypeVariable<?>) typeArgument, targetType);
        } else {
            throw new IllegalArgumentException("Unsupported type argument: " + typeArgument);
        }
    }

    return argumentClasses;
}

private static Class<?> findBoundClass(TypeVariable<?> typeVariable, Class<?> targetType) {
    // Recursively search for the bound class for a given type variable
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0) {
        return null;
    }

    // Check if any of the bounds are a Class
    for (Type bound : bounds) {
        if (bound instanceof Class) {
            return (Class<?>) bound;
        } else if (bound instanceof TypeVariable) {
            return findBoundClass((TypeVariable<?>) bound, targetType);
        }
    }

    // No bound is a class, return null
    return null;
}

