public Mappings diffStructure(String tableName, Mappings mappings) {
    // Create a new Mappings object with the same fields as the input mappings, but with no source config
    Mappings diffMappings = new Mappings(tableName, mappings.getMappings().values());

    // Iterate over the fields in the input mappings
    for (String fieldName : mappings.getFields()) {
        // Get the field object for the current field
        Field field = mappings.getField(fieldName);

        // Check if the field exists in the diffMappings
        if (diffMappings.getField(fieldName) == null) {
            // If the field does not exist in the diffMappings, add it with the same type and properties as the original field
            diffMappings.addField(fieldName, field.getType(), field.getProperties());
        }
    }

    // Return the diffMappings object
    return diffMappings;
}

