protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new LinkedList<>();
    long duration = end - start;
    while (duration > FETCH_DATA_DURATION) {
        long splitTime = start + FETCH_DATA_DURATION;
        timeRanges.add(new TimeRange(start, splitTime));
        start = splitTime;
        duration = end - start;
    }
    timeRanges.add(new TimeRange(start, end));
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;
    for (long i = start; i < end; i += duration) {
        long startTime = i;
        long endTime = (i + duration <= end) ? (i + duration) : end;
        timeRanges.add(new TimeRange(startTime, endTime));
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;
    long startTime = start;
    long endTime = start + duration;
    while (endTime <= end) {
        timeRanges.add(new TimeRange(startTime, endTime));
        startTime = endTime;
        endTime = startTime + duration;
    }
    timeRanges.add(new TimeRange(startTime, end));
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;

    while (start + duration <= end) {
        timeRanges.add(new TimeRange(start, start + duration));
        start += duration;
    }

    if (start < end) {
        timeRanges.add(new TimeRange(start, end));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    long startTime = start;
    long endTime = end;

    while (startTime <= endTime) {
        long fetchDataDuration = 60000; // 1 minute
        long endOfCurrentRange = startTime + fetchDataDuration;

        if (endOfCurrentRange > endTime) {
            endOfCurrentRange = endTime;
        }

        TimeRange timeRange = new TimeRange(startTime, endOfCurrentRange);
        timeRanges.add(timeRange);

        startTime = endOfCurrentRange;
    }

    return timeRanges;
}

