static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket + (86400 * dayStep);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % dayStep) + 1;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = (timeBucket / 100000000) * 100000000;
    long month = (timeBucket / 1000000 - year * 100) * 100;
    long day = (timeBucket / 100 - year * 10000 - month * 100) * 100;
    long hour = (timeBucket / 100 - year * 10000 - month * 100 - day * 100) * 100;
    long minute = (timeBucket / 10 - year * 1000000 - month * 100000 - day * 10000 - hour * 1000) * 100;
    long second = (timeBucket - year * 100000000 - month * 10000000 - day * 1000000 - hour * 100000 - minute * 1000);

    int step = dayStep / 10;
    int remaining = dayStep % 10;

    long newYear = year + step * 100000000;
    long newMonth = month + step * 100;
    long newDay = day + step * 100;
    long newHour = hour + step * 100;
    long newMinute = minute + step * 100;
    long newSecond = second + remaining;

    return newYear * 100000000 + newMonth * 1000000 + newDay * 100000 + newHour * 10000 + newMinute * 1000 + newSecond;
}

public class CompressTimeBucket{
    /** 
     * Follow the dayStep to re-format the time bucket literal long value. Such as, in dayStep == 11, 20000105 re-formatted time bucket is 20000101, 20000115 re-formatted time bucket is 20000112, 20000123 re-formatted time bucket is 20000123
     */
    public static long compressTimeBucket(long timeBucket, int dayStep) {
        long recalculatedTimeBucket = timeBucket;
        for (int i = 0; i < dayStep; i++) {
            recalculatedTimeBucket = recalculatedTimeBucket - 2;
            if (recalculatedTimeBucket < 0) {
                recalculatedTimeBucket = recalculatedTimeBucket + 31;
            }
        }
        return recalculatedTimeBucket;
    }
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the number of days in the time bucket
    int numDays = (int) timeBucket / 10000;

    // Calculate the number of days to skip
    int numDaysToSkip = dayStep - 1;

    // Calculate the new day value
    int newDay = (numDays + numDaysToSkip) % 10;

    // Generate the new time bucket
    return (newDay * 10000) + timeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        int cp = str.charAt(i++);
        if (cp < 0x80) {
            size++;
        } else if (cp < 0x800) {
            size += 2;
        } else if (cp < 0xd800 || cp >= 0xe000) {
            size += 3;
        } else {
            cp = ((cp & 0x3ff) << 10) | (str.charAt(i++) & 0x3ff);
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(str, index, len) {
    char[] chars = str.toCharArray();
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = chars[i];
        if (c <= 0x7f) {
            size++;
        } else if (c <= 0x7ff) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            size += 4;
        } else {
            size += 3;
        }
    }
    return size;
}

