public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the midpoint of the box along the x axis
    double midpoint = box.getX() + (box.getWidth() / 2);

    // Create two new boxes with the same width and height as the original box
    Box2D box1 = new Box2D(box.getX(), box.getY(), midpoint - box.getX(), box.getHeight());
    Box2D box2 = new Box2D(midpoint, box.getY(), box.getWidth() - (midpoint - box.getX()), box.getHeight());

    // Return the two new boxes as a pair
    return new ImmutablePair<Box2D, Box2D>(box1, box2);
}

