    float width = box.getWidth() / 2;
    Box2D box1 = new Box2D(new Vector2(x - width, box.getMin().y), new Vector2(x + width, box.getMax().y));
    Box2D box2 = new Box2D(new Vector2(x + width, box.getMin().y), new Vector2(x - width, box.getMax().y));
    return new Pair<Box2D, Box2D>(box1, box2);
}

