public static StackMapFrame createStackMapFrame(List<StackMapType> stackMapTableEntries, int start, int end) {
    for (int i = start; i < end; i++) {
        StackMapType type = stackMapTableEntries.get(i);
        switch (type) {
            case AbstractObject:
                stackMapTableEntries.set(i, StackMapType.AbstractObject);
                break;
            case AbstractValue:
                stackMapTableEntries.set(i, StackMapType.AbstractValue);
                break;
            case Double:
                stackMapTableEntries.set(i, StackMapType.Double);
                break;
            case Float:
                stackMapTableEntries.set(i, StackMapType.Float);
                break;
            case Long:
                stackMapTableEntries.set(i, StackMapType.Long);
                break;
            case Integer:
                stackMapTableEntries.set(i, StackMapType.Integer);
                break;
            case Null:
                stackMapTableEntries.set(i, StackMapType.Null);
                break;
            case InitializedObject:
                stackMapTableEntries.set(i, StackMapType.InitializedObject);
                break;
            case UninitializedObject:
                stackMapTableEntries.set(i, StackMapType.UninitializedObject);
                break;
            default:
                throw new IllegalArgumentException("Unknown stack map type: " + type.name());
        }
    }

    return new StackMapFrame(stackMapTableEntries);
}

private void putAbstractTypes(final int start, final int end) {
    StackMapTableEntry entry = null;
    for (int i = start; i < end; i++) {
        ObjectType type = currentFrame.get(i);
        if (type instanceof NullType) {
            entry = new ObjectType(0, 0);
        } else if (type instanceof IntegerType) {
            entry = new IntegerType(0);
        } else if (type instanceof FloatType) {
            entry = new FloatType(0);
        } else if (type instanceof LongType || type instanceof DoubleType) {
            entry = new LongType(0, 0);
        } else if (type instanceof TopType || type instanceof ObjectType || type instanceof UninitializedType) {
            entry = new ObjectType(0, 0);
        } else {
            throw new IllegalStateException("Unexpected type: " + type);
        }
        stackMapTableEntries.add(entry);
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        VerificationTypeInfo info = currentFrame.get(i);
        if (info.isLong() || info.isDouble()) {
            stackMapTableEntries.add(new StackMapTableEntry1(VerificationTypeInfo.ITEM_LONG, info.getTag()));
        } else if (info.isNull()) {
            stackMapTableEntries.add(new StackMapTableEntry0(VerificationTypeInfo.ITEM_NULL));
        } else if (info.isObject()) {
            stackMapTableEntries.add(new StackMapTableEntry2(VerificationTypeInfo.ITEM_Object, info.getReference()));
        } else if (info.isUninitialized()) {
            stackMapTableEntries.add(new StackMapTableEntry1(VerificationTypeInfo.ITEM_UNINITIALIZED, info.getOffset()));
        } else {
            stackMapTableEntries.add(new StackMapTableEntry0(VerificationTypeInfo.ITEM_TOP));
        }
    }
}

