public Character convertToCharacter(Class<?> type, Object value) throws Exception {
    if (type == Character.class) {
        return (Character) value;
    }

    if (type == String.class) {
        return ((String) value).charAt(0);
    }

    if (type == int.class || type == Integer.class) {
        return (char) ((Number) value).intValue();
    }

    if (type == long.class || type == Long.class) {
        return (char) ((Number) value).longValue();
    }

    if (type == float.class || type == Float.class) {
        return (char) ((Number) value).floatValue();
    }

    if (type == double.class || type == Double.class) {
        return (char) ((Number) value).doubleValue();
    }

    if (type == char.class) {
        return (char) value;
    }

    throw new Exception("Unsupported conversion from " + value.getClass().getName() + " to " + type.getName());
}

public Character convertToType(Class<?> type, Object value) throws Exception {
    if (value == null) {
        return null;
    }

    if (type.isAssignableFrom(String.class)) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("Value is not a single character string");
        }
    } else if (type.isAssignableFrom(Character.class)) {
        return (Character) value;
    } else {
        throw new IllegalArgumentException("Unsupported type " + type.getName());
    }
}

