    StringBuilder out = new StringBuilder(sz);
    boolean hadSlash = false;
    boolean inChar = false;

    for (int i = 0; i < sz; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            hadSlash = true;
            inChar = true;
            continue;
        }
        if (hadSlash) {
            hadSlash = false;
            switch (c) {
                case 'n':
                    out.append('\n');
                    break;
                case 'r':
                    out.append('\r');
                    break;
                case 't':
                    out.append('\t');
                    break;
                case '\\':
                    out.append('\\');
                    break;
                case '\'':
                    out.append('\'');
                    break;
                case '"':
                    out.append('\"');
                    break;
                default:
                    if (c == '/') {
                        out.append('\\');
                        break;
                    }
                    int hex = Character.digit(c, 16);
                    if (hex == -1) {
                        out.append(c);
                    } else {
                        if (i + 2 < sz && str.charAt(i + 1) == 'u') {
                            int hex9 = Integer.parseInt(str.substring(i + 2, i + 6), 16);
                            if (hex9 > 0xfffd) {
