public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue == null) {
        // If byteArrayValue is null, we need to put `byteLength` null bytes into the byte vector
        byteLength = Math.max(byteLength, 0);
    } else {
        byteLength = Math.min(byteLength, byteArrayValue.length - byteOffset);
    }

    // Check if the byte vector needs to be enlarged
    int requiredCapacity = byteOffset + byteLength;
    if (requiredCapacity > contents.length) {
        // Enlarge the byte vector by the required amount
        byte[] newContents = new byte[requiredCapacity];
        System.arraycopy(contents, 0, newContents, 0, contents.length);
        contents = newContents;
    }

    // Copy the bytes from byteArrayValue to the byte vector
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, contents, byteOffset, byteLength);
    }

    return this;
}

