public int addConstantNameAndType(final String name,final String descriptor){
    if(name == null || descriptor == null){
        throw new IllegalArgumentException("Name and descriptor cannot be null.");
    }

    for(int i = 1; i < constantPool.size(); i++){
        ConstantInfo constantInfo = constantPool.get(i);
        if(constantInfo instanceof ConstantNameAndTypeInfo){
            ConstantNameAndTypeInfo constantNameAndTypeInfo = (ConstantNameAndTypeInfo) constantInfo;
            if(constantNameAndTypeInfo.getName().equals(name) && constantNameAndTypeInfo.getDescriptor().equals(descriptor)){
                return i;
            }
        }
    }

    ConstantNameAndTypeInfo constantNameAndTypeInfo = new ConstantNameAndTypeInfo(ConstantType.CONSTANT_NameAndType, name, descriptor);
    constantPool.add(constantNameAndTypeInfo);

    return constantPool.size() - 1;
}

