            return constant;
        }
    }

    // If not, create a new Constant_NameAndType_info and add it to the constant pool
    Constant_NameAndType_info newConstant = new Constant_NameAndType_info();
    newConstant.setName(name);
    newConstant.setDescriptor(descriptor);
    constantPool.add(newConstant);
    return newConstant;
}

