    // Prepare the output bucket
    Set<Integer> newBucket = new HashSet<>();

    // Iterate over the vertices in the min label bucket
    for (int vertex : bucketsByLabel.get(minLabel)) {
        // Move the vertex to the new bucket
        newBucket.add(vertex);
        // Update the label of the vertex
        labels.set(vertex, 0);
    }

    // Clear the min label bucket
    bucketsByLabel.set(minLabel, null);

    // Move the new bucket to the min label position
    bucketsByLabel.set(minLabel, newBucket);
