    // Make sure the node is not null
    if (node == null) {
        return false;
    }

    // Check if the node is the first node in the list
    if (node.prev == null) {
        // If the node is the first node, set the next node as the new first node
        node.next.prev = null;
        first = node.next;
    } else {
        // If the node is not the first node, set the previous node's next node as the node's next node
        node.prev.next = node.next;
    }

    // Check if the node is the last node in the list
    if (node.next == null) {
        // If the node is the last node, set the previous node as the new last node
        node.prev.next = null;
        last = node.prev;
    } else {
        // If the node is not the last node, set the next node's previous node as the node's previous node
        node.next.prev = node.prev;
    }

    return true;
}

