    // Initialize variables
    List<Integer> suffixSum = new ArrayList<>();
    long sumOfElements = 0L;

    // Compute suffix sum and sum of elements
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sumOfElements += bounds.get(i);
        suffixSum.add(i, (int) sumOfElements);
    }

    // Return the computed pair
