private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();

    for (E edge : graph.edgeSet()) {
        List<Pair<Integer,Integer>> separator = new ArrayList<>();
        for (E neighbor : graph.getNeighborListOf(edge)) {
            for (E pivot = graph.getPrevEdge(neighbor, edge); pivot != null; pivot = graph.getPrevEdge(neighbor, pivot)) {
                separator.add(new Pair<Integer,Integer>(pivot.getSource(), pivot.getDest()));
                if (pivot == edge) {
                    break;
                }
            }
        }
        separatorList.add(new Pair<List<Pair<Integer,Integer>>,E>(separator, edge));
    }

    return separatorList;
}

