public ByteVector putInt(final int intValue) { 
    // convert the int value to a byte array 
    byte[] intBytes = ByteVector.toBytes(intValue); 

    // determine the number of bytes the int value occupies 
    int numBytes = intBytes.length; 

    // check if the byte vector needs to be enlarged 
    if (this.size() < this.capacity() - numBytes) { 
        // enlarge the vector 
        this.enlarge(); 
    } 

    // put the int value into the byte vector 
    for (int i = 0; i < numBytes; i++) { 
        this.put(this.size() - numBytes + i, intBytes[i]); 
    } 

    return this; 
}

