public static Class<?> resolveBound(TypeVariable<?> typeVariable) {
    // Safety check for null values
    if (typeVariable == null) {
      return Unknown.class;
    }

    // Attempt to resolve the bound from the type variable's declared bounds
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
      return Unknown.class;
    }

    // Return the first bound that is not an instance of TypeVariable<?>
    for (Type bound : bounds) {
      if (bound instanceof Class<?>) {
        return (Class<?>) bound;
      }
    }

    return Unknown.class;
  }

public static Class<?> resolveBound(TypeVariable<?> typeVariable) {
    Type superClass = typeVariable.getGenericDeclaration();
    while (superClass != null) {
        if (superClass instanceof Class<?>) {
            return (Class<?>) superClass;
        } else if (superClass instanceof ParameterizedType) {
            Type[] actualTypeArguments = ((ParameterizedType) superClass).getActualTypeArguments();
            for (Type type : actualTypeArguments) {
                if (type instanceof TypeVariable<?> && ((TypeVariable<?>) type).getName().equals(((TypeVariable<?>) typeVariable).getName())) {
                    // Recursively resolve the bound of the current type variable
                    Type resolveBound = resolveBound((TypeVariable<?>) type);
                    if (resolveBound != null) {
                        // Return the resolved bound
                        return resolveBound;
                    }
                }
            }
        }
        // Move on to the super class
        superClass = ((Class<?>) superClass).getGenericSuperclass();
    }
    // Unable to resolve the bound
    return Unknown.class;
}

