public static boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Create a new graph that contains only the given vertices
    Graph<V,E> subgraph = new Graph<>();
    for (V vertex : vertices) {
        subgraph.addVertex(vertex);
    }
    for (V vertex : subgraph.getVertices()) {
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                subgraph.addEdge(vertex, neighbor);
            }
        }
    }

    // Check if the subgraph is complete
    return subgraph.isComplete();
}

public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.size() == 0) {
        return true;
    }

    for (V vertex : vertices) {
        if (!graph.neighbors(vertex).containsAll(vertices)) {
            return false;
        }
    }

    return true;
}

public static boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.size() == 0) {
        return true;
    }

    for (V vertex : graph.vertices()) {
        if (!vertices.contains(vertex)) {
            continue;
        }

        for (V neighbor : graph.neighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }

    return true;
}

