private void pop(final String descriptor) {
    // Check if the descriptor is a method descriptor
    if (descriptor.indexOf('(') != -1) {
        // Get the argument types from the descriptor
        final String[] argumentTypes = getArgumentTypes(descriptor);

        // Pop each argument from the stack
        for (String argumentType : argumentTypes) {
            pop(argumentType);
        }
    } else {
        // Pop a single value from the stack
        pop(descriptor);
    }
}

private void pop(final String type) {
    // Check if the type is an array type
    if (type.endsWith("[]")) {
        // Pop the array and its contents from the stack
        // NOTE: This assumes that the array element type is a primitive type
        pop(type.substring(0, type.length() - 2));
        pop("[" + type.substring(0, type.length() - 2) + "");
    } else {
        // Pop a single value from the stack
        pop(type);
    }
}

private void pop(final String descriptor) throws InvalidTypeException {
    if (descriptor.startsWith("(")) {
        // This is a method descriptor
        final int numArgumentTypes = Type.getArgumentTypes(descriptor).length;
        for (int i = 0; i < numArgumentTypes; i++) {
            outputFrame.pop();
        }
    } else {
        // This is a type descriptor
        final Type type = Type.getType(descriptor);
        for (int i = 0; i < type.getDimensions(); i++) {
            outputFrame.pop();
        }
    }
}

public void pop(final String descriptor) {
    if (descriptor.contains("(")) {
        // It's a method descriptor, so we need to pop the argument types too
        final String[] argTypes = descriptor.substring(1, descriptor.length() - 2).split("\\);");
        for (String argType : argTypes) {
            final Type type = constantPool.get(argType).getType();
            if (type.isReference()) {
                stack.pop(referenceValue(type));
            } else {
                stack.pop(type);
            }
        }
    }
    final Type type = constantPool.get(descriptor).getType();
    stack.pop(type);
}

public void pop(String descriptor) {
    switch (descriptor.charAt(0)) {
        case 'B':
            pop();
