    }
}

private void pop(final String descriptor) {
    if (descriptor.charAt(0) == '(') {
        // Pop argument types from the stack
        while (descriptor.charAt(0) != ')') {
            pop();
            descriptor = descriptor.substring(1); // Remove popped type from descriptor
        }
        // Remove closing ')'
        descriptor = descriptor.substring(1);
    } else {
        // Pop one abstract type from the stack
        pop();
    }
}

