public List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize the upper bounds with the first key
    List<Integer> upperBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        upperBounds.add(keys.get(i));
    }

    // Iterate over the keys and update the upper bounds as needed
    for (int i = 1; i < keys.size(); i++) {
        // If the current key is less than the previous key, update the upper bound for the previous key
        if (keys.get(i) < keys.get(i - 1)) {
            upperBounds.set(i - 1, keys.get(i));
        }
    }

    return upperBounds;
}

