    }

    // Find the next node
    Node nextNode = currentNode.getNextNode();

    // If the next node is not real, find its real counterpart
    if (!nextNode.isReal()) {
        nextNode = nextNode.getRealCounterpart();
    }

    // Return the edge between the current node and the next node
    return new Edge(currentNode, nextNode);
