                    if (range.contains(time)) {
                        isInRange = true;
                        break;
                    }
                }
                if (isInRange) {
                    threadSnapshots.add(new ThreadSnapshot(threadName, time, duration));
                }
            } catch (NumberFormatException e) {
                throw new IOException("Invalid data in file", e);
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> loadThreadSnapshotsWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges cannot be null or empty");
    }
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (FileInputStream stream = new FileInputStream(file)) {
        BriefWriter reader = new BriefWriter(stream, "UTF-8");
        while ((reader.nextRecord()) != null) {
            String type = reader.getString(0);
            long executeTime = reader.getLong(1);
            long waitTime = reader.getLong(2);
            long lockedTime = reader.getLong(3);
            String threadName = reader.getString(4);
            String trace = reader.getString(5);
            if (timeRanges.stream().anyMatch(r -> r.contains(executeTime))) {
                snapshots.add(new ThreadSnapshot(type, executeTime, waitTime, lockedTime, threadName, trace));
            }
        }
    }
    return Collections.unmodifiableList(snapshots);
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    ObjectInputStream inputStream = new ObjectInputStream(new FileInputStream(file));
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try {
        while (true) {
            ThreadSnapshot threadSnapshot = (ThreadSnapshot) inputStream.readObject();
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timeRange.contains(threadSnapshot.getTimestamp())) {
                    threadSnapshots.add(threadSnapshot);
                    break;
                }
            }
        }
    } finally {
        inputStream.close();
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (FileInputStream stream = new FileInputStream(file)) {
        List<String> lines = IOUtils.readLines(stream, StandardCharsets.UTF_8);
        for (String line : lines) {
            String[] split = line.split(",");
            if (split.length > 1) {
                Date date = new Date(Long.parseLong(split[0]));
                List<Date> timeRange = timeRanges.stream()
                        .map(ProfileAnalyzeTimeRange::getStartTime)
                        .collect(Collectors.toList());
                if (timeRange.contains(date)) {
                    threadSnapshots.add(new ThreadSnapshot(date, Integer.parseInt(split[1])));
                }
            }
        }
    }
    return threadSnapshots;
}

